gcV(){return"\u0412\u044b\u043a\u0430\u0440\u044b\u0441\u0442\u043e\u045e\u0432\u0430\u0439\u0446\u0435 \u043d\u0430\u0448\u044b \u043c\u0430\u0433\u0443\u0442\u043d\u044b\u044f \u043c\u0443\u043b\u044c\u0442\u0438\u043c\u0435\u0434\u044b\u0439\u043d\u044b\u044f \u0456\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u044b \u0434\u043b\u044f \u0441\u0442\u0432\u0430\u0440\u044d\u043d\u043d\u044f \u043a\u0443\u0440\u0441\u0430\u045e, \u044f\u043a\u0456\u044f \u0432\u044b\u0434\u0437\u044f\u043b\u044f\u044e\u0446\u0446\u0430. \u041d\u0435\u0437\u0430\u043b\u0435\u0436\u043d\u0430 \u0430\u0434 \u0442\u0430\u0433\u043e, \u0446\u0456 \u0432\u044b\u043a\u0430\u0440\u044b\u0441\u0442\u043e\u045e\u0432\u0430\u0435\u0446\u0435 \u0432\u044b \u0432\u0456\u0434\u044d\u0430, \u0456\u043d\u0442\u044d\u0440\u0430\u043a\u0442\u044b\u045e\u043d\u044b\u044f \u0432\u0456\u043a\u0442\u0430\u0440\u044b\u043d\u044b \u0446\u0456 \u0432\u0456\u0434\u044d\u0430\u043a\u0430\u043d\u0444\u0435\u0440\u044d\u043d\u0446\u044b\u0456 \u045e \u0440\u044d\u0430\u043b\u044c\u043d\u044b\u043c \u0447\u0430\u0441\u0435, \u043d\u0430\u0448\u0430 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 \u043f\u0440\u0430\u043f\u0430\u043d\u0443\u0435 \u0456\u0434\u044d\u0430\u043b\u044c\u043d\u044b\u044f \u0444\u0443\u043d\u043a\u0446\u044b\u0456 \u0434\u043b\u044f \u0441\u0442\u0432\u0430\u0440\u044d\u043d\u043d\u044f \u043f\u0440\u044b\u0432\u0430\u0431\u043d\u0430\u0433\u0430 \u043a\u0430\u043d\u0442\u044d\u043d\u0442\u0443, \u044f\u043a\u0456 \u043f\u0440\u044b\u043d\u043e\u0441\u0456\u0446\u044c \u0434\u0430\u0445\u043e\u0434."},
