gdd(){return"\u10e9\u10d0\u10e2\u10d5\u10d8\u10e0\u10d7\u10d5\u10d0"},
gdz(a){return"\u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8"},
gdu(){return"\u10d0\u10e0\u10d0\u10e4\u10d4\u10e0\u10d8 \u10d8\u10dc\u10e2\u10d4\u10e0\u10dc\u10d4\u10e2\u10d8\u10e1 \u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8. \u10d2\u10d7\u10ee\u10dd\u10d5\u10d7, \u10d2\u10d0\u10d3\u10d0\u10d0\u10db\u10dd\u10ec\u10db\u10dd\u10d7 \u10d7\u10e5\u10d5\u10d4\u10dc\u10d8 \u10d9\u10d0\u10d5\u10e8\u10d8\u10e0\u10d8"},
