gd3(){return"\u041f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 \u0434\u0438\u0437\u0430\u0458\u043d\u0438\u0440\u0430\u043d\u0430 \u0437\u0430 \u043a\u0440\u0435\u0430\u0442\u043e\u0440\u0438 \u043d\u0430 \u0435\u0434\u0443\u043a\u0430\u0442\u0438\u0432\u0435\u043d \u0441\u043e\u0434\u0440\u0436\u0438\u043d\u0430 \u0438 \u0441\u043b\u0435\u0434\u0431\u0435\u043d\u0438\u0446\u0438. \u0417\u0430\u0440\u0430\u0431\u043e\u0442\u0435\u0442\u0435 \u043f\u0430\u0440\u0438 \u0443\u0447\u0435\u0458\u045c\u0438 \u0438\u043b\u0438 \u0443\u0447\u0435\u0442\u0435 \u043e\u0434 \u043a\u0440\u0435\u0430\u0442\u043e\u0440\u0438 \u043d\u0430 \u0441\u043e\u0434\u0440\u0436\u0438\u043d\u0430 \u0438 \u0435\u0434\u0443\u043a\u0430\u0442\u043e\u0440\u0438."},
ge3(){return"\u041f\u0440\u0438\u0434\u0440\u0443\u0436\u0435\u0442\u0435 \u0441\u0435 \u043d\u0430 \u0432\u0438\u0434\u0435\u043e\u0441\u043e\u0441\u0442\u0430\u043d\u0446\u0438\u0442\u0435, \u0430\u043a\u043e \u0432\u0435\u045c\u0435 \u0441\u0442\u0435 \u0441\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0430\u043b\u0435."},
gcP(){return"\u0414\u043e\u0431\u0438\u0458\u0442\u0435 \u0458\u0430 \u043d\u043e\u0432\u0430\u0442\u0430 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430"},
gdl(){return"\u0417\u0430\u043f\u043e\u0437\u043d\u0430\u0458\u0442\u0435 \u0458\u0430 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430\u0442\u0430"},
