gdE(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u0443"},
gdD(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044e"},
gep(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0438\u043c\u0435\u043d\u0438"},
geq(){return"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u0438"},
gdC(){return"\u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e \u0432 \u044d\u0442\u043e\u043c \u0440\u0430\u0437\u0434\u0435\u043b\u0435"},
gcQ(a){return"\u041f\u043e\u0438\u0441\u043a"},
gdV(){return"\u0442\u043e\u043c\u0443 \u043d\u0430\u0437\u0430\u0434"},
ge7(){return"\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c\u0441\u044f"},
gdw(){return"\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435"},
gcF(){return"\u0431\u043e\u043b\u044c\u0448\u0435"},
gcE(){return"\u043c\u0435\u043d\u044c\u0448\u0435"},
gdU(){return"\u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438"},
ge0(){return"\u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c"},
gca(a){return"\u0417\u0430\u043a\u0440\u044b\u0442\u044c"},
gex(a){return"\u0412\u0435\u0440\u0441\u0438\u044f"},
gea(a){return"\u0421\u043a\u0430\u0447\u0430\u0442\u044c"},
ged(){return"\u042d\u0442\u043e\u0442 \u043f\u043e\u0447\u0442\u043e\u0432\u044b\u0439 \u0430\u0434\u0440\u0435\u0441 \u043d\u0435\u0432\u0435\u0440\u0435\u043d"},
ge4(){return"\u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0441\u0432\u043e\u044e \u043f\u043e\u0447\u0442\u0443"},
gey(){return"\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 edhomy?"},
geb(){return"Edhomy \u2014 \u044d\u0442\u043e \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0442\u044c \u0434\u0435\u043d\u044c\u0433\u0438 \u043a\u0430\u043a \u043f\u0435\u0434\u0430\u0433\u043e\u0433 \u0438\u043b\u0438 \u0441\u043e\u0437\u0434\u0430\u0442\u0435\u043b\u044c \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u0430 \u0447\u0435\u0440\u0435\u0437 \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0438 \u0438 \u0447\u0430\u0435\u0432\u044b\u0435. \u041f\u043e\u0434\u043f\u0438\u0441\u0447\u0438\u043a\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u044e\u0442 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u043c \u0446\u0435\u043d\u0430\u043c \u0438 \u043e\u0431\u0443\u0447\u0430\u044e\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u043a\u0443\u0440\u0441\u044b \u043d\u0430 \u0431\u0430\u0437\u0435 \u0418\u0418, \u0432\u0438\u0434\u0435\u043e\u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0438 \u0438 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0435 \u0432\u0438\u0434\u0435\u043e, \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u043c\u044b\u0435 Globals."},
ge6(){return"\u041c\u043e\u0433\u0443 \u043b\u0438 \u044f \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0442\u044c \u0434\u0435\u043d\u044c\u0433\u0438 \u0432 \u044d\u0442\u043e\u043c \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438?"},
